    auto select=[&](const String& id){if(commands)for(int i=0;i<(int)shortcutCommands().size();++i)if(shortcutCommands()[(size_t)i].id==id){commands->setSelectedId(i+1,dontSendNotification);commands->onChange();}};
    auto click=[&](const String& id){if(auto* button=dynamic_cast<TextButton*>(child(id)))button->onClick();};
    auto prefs=root.getChildFile("data/shortcuts.json");
    if(transportTicks==2220){perform(stop);cancelNoteTool(false);closeCommandPalette();PopupMenu::dismissAllActiveMenus();project=emptyProject();project.patterns[0].lanes[7]={{0,4,60,.8f}};selectedTrack=7;project.loop=true;project.songMode=false;typingEnabled=true;typingTranspose=0;octave=3;undoStack.clear();redoStack.clear();publish();shortcutSettings={};perform(shortcutsOpen);dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeShortcutDialog",dialog&&dialog->findChildWithID("shortcut-panel"));}
    if(transportTicks==2230){select("transport.toggle");if(capture)capture->keyPressed(KeyPress('J',ModifierKeys::ctrlModifier,'j'));put("nativeShortcutCapture",capture&&capture->getText()=="Ctrl+J"&&!engine->playing.load());click("shortcut-set");click("shortcut-apply");put("nativeShortcutApply",shortcutHint("transport.toggle")=="Ctrl+J"&&undoStack.empty());ShortcutSettings loaded;put("nativeShortcutPersist",loadShortcuts(prefs,loaded).wasOk()&&loaded==shortcutSettings);if(dialog){PNGImageFormat png;FileOutputStream output(transportReport.getSiblingFile("native-shortcuts-dialog.png"));if(output.openedOk())png.writeImageToStream(dialog->createComponentSnapshot(dialog->getLocalBounds()),output);dialog->exitModalState(0);}}
    if(transportTicks==2240){keyPressed(KeyPress(KeyPress::spaceKey));put("nativeShortcutOldKey",!engine->playing.load());transportFrames=engine->processedFrames.load();keyPressed(KeyPress('J',ModifierKeys::ctrlModifier,'j'));}
    if(transportTicks==2260){put("nativeShortcutAudio",engine->playing.load()&&engine->processedFrames.load()>transportFrames&&engine->observedPeak.load()>.001f);keyPressed(KeyPress('J',ModifierKeys::ctrlModifier,'j'));put("nativeShortcutStop",!engine->playing.load());perform(shortcutsOpen);}
    if(transportTicks==2270){put("nativeShortcutStop",(bool)transportResults["nativeShortcutStop"]&&engine->position.load()==0);select("project.open");if(capture)capture->keyPressed(KeyPress('J',ModifierKeys::ctrlModifier,'j'));click("shortcut-set");auto* message=dynamic_cast<Label*>(child("shortcut-message"));put("nativeShortcutConflict",message&&message->getText().contains("already used")&&shortcutHint("project.open")=="Ctrl+O");select("transport.toggle");click("shortcut-disable");click("shortcut-apply");put("nativeShortcutDisable",shortcutHint("transport.toggle").isEmpty());click("shortcut-default");click("shortcut-apply");put("nativeShortcutDefault",shortcutHint("transport.toggle")=="Space");select("project.open");if(capture)capture->keyPressed(KeyPress('J',ModifierKeys::ctrlModifier,'j'));click("shortcut-set");if(dialog)dialog->exitModalState(0);}
    if(transportTicks==2280){put("nativeShortcutCancel",shortcutHint("project.open")=="Ctrl+O");keyPressed(KeyPress('Z',ModifierKeys{},'z'));put("nativeShortcutPiano",heldKeys.count('Z')&&heldKeys.at('Z').pitch==48&&pianoPitchActive(48));releaseKeys();auto next=shortcutSettings;setShortcut(next,"transport.toggle","Ctrl+J");applyShortcutSettings(next,shortcutRevision,shortcutFileToken(prefs));showCommandPalette();keyPressed(KeyPress('J',ModifierKeys::ctrlModifier,'j'));put("nativeShortcutTextFocus",commandPalette&&commandPalette->isVisible()&&!engine->playing.load());closeCommandPalette();bool recovered=false;auto callback=fitMainWindow;fitMainWindow=[&]{recovered=true;};keyPressed(KeyPress('H',ModifierKeys::ctrlModifier|ModifierKeys::shiftModifier,'h'));fitMainWindow=callback;put("nativeShortcutRecovery",recovered);applyShortcutSettings({},shortcutRevision,shortcutFileToken(prefs));perform(stop);}
